import{_ as t,o,c as i,aj as r}from"./chunks/framework.BwH0p-pt.js";const u=JSON.parse('{"title":"Microsoft SSO","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/configuration/microsoft-sso.md","filePath":"2.1/configuration/microsoft-sso.md","lastUpdated":1788942616000}'),s={name:"2.1/configuration/microsoft-sso.md"};function n(a,e,l,c,h,d){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="microsoft-sso" tabindex="-1">Microsoft SSO <a class="header-anchor" href="#microsoft-sso" aria-label="Permalink to &quot;Microsoft SSO&quot;">​</a></h1><p>Microsoft SSO lets your team sign in to UnoPim with their existing Microsoft work account instead of a separate UnoPim password. Once it is switched on, a <strong>Sign in with Microsoft</strong> button appears on the login page.</p><p>This page walks through the whole setup from scratch. No prior Azure experience is assumed.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>Your team signs in with the Microsoft account they already use.</li><li>One less password for people to manage and for you to reset.</li><li>Removing someone from your Microsoft directory stops them signing in to UnoPim.</li><li>The normal email and password login keeps working alongside it.</li></ul><div class="warning custom-block"><p class="custom-block-title">Signing in is not the same as getting access</p><p>Microsoft only confirms <strong>who</strong> somebody is. It does not decide what they are allowed to do in UnoPim.</p><p>Every person who signs in with Microsoft must already have a UnoPim user account with the <strong>same email address</strong> and a role. If that account does not exist, the login is refused. You will create one in <strong>Step 8</strong>.</p></div><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You need three things from Microsoft: a <strong>Tenant ID</strong>, a <strong>Client ID</strong>, and a <strong>Client Secret</strong>. Steps 1 to 5 explain how to get them. You also need a Microsoft directory that you are an administrator of.</p><hr><h2 id="step-1-—-make-sure-you-have-a-directory-you-control" tabindex="-1">Step 1 — Make sure you have a directory you control <a class="header-anchor" href="#step-1-—-make-sure-you-have-a-directory-you-control" aria-label="Permalink to &quot;Step 1 — Make sure you have a directory you control&quot;">​</a></h2><p>This trips up most first-timers, so check it first.</p><p>If you sign in to the Azure portal with a personal Microsoft account (outlook.com, hotmail.com, gmail.com), Microsoft may put you in a placeholder directory called <strong>&quot;Microsoft Services&quot;</strong>. That directory belongs to Microsoft. You cannot add users or applications to it.</p><p>Open <a href="https://portal.azure.com" target="_blank" rel="noreferrer">portal.azure.com</a> and go to <strong>Microsoft Entra ID → Overview</strong>. Compare what you see:</p><table tabindex="0"><thead><tr><th>What you see</th><th>Meaning</th></tr></thead><tbody><tr><td>Primary domain is a long code like <code>f8cdef31-a31e-…</code></td><td>Not usable. Continue below.</td></tr><tr><td>Your role shows <strong>User</strong></td><td>Not usable. Continue below.</td></tr><tr><td>Primary domain ends in <code>.onmicrosoft.com</code> and your role is <strong>Global Administrator</strong></td><td>You are ready. Go to Step 2.</td></tr></tbody></table><p><strong>If it is not usable</strong>, get a proper directory one of these ways:</p><ul><li><strong>Sign up for Azure</strong> at <a href="https://azure.microsoft.com/free" target="_blank" rel="noreferrer">azure.microsoft.com/free</a>. This creates a <strong>Default Directory</strong> where you are the administrator. A card is required for identity verification, but the directory itself is free.</li><li><strong>Ask your IT team.</strong> If your company already uses Microsoft 365, a directory exists. Ask an administrator to complete Steps 3 to 7 for you.</li></ul><div class="tip custom-block"><p class="custom-block-title">Do not try to create a new tenant</p><p>The <strong>Manage tenants → Create</strong> button now asks for a paid licence. You almost certainly do not need it — signing up for Azure already gives you a <strong>Default Directory</strong> that works.</p></div><hr><h2 id="step-2-—-copy-the-redirect-uri-from-unopim" tabindex="-1">Step 2 — Copy the Redirect URI from UnoPim <a class="header-anchor" href="#step-2-—-copy-the-redirect-uri-from-unopim" aria-label="Permalink to &quot;Step 2 — Copy the Redirect URI from UnoPim&quot;">​</a></h2><p>Microsoft needs to know where to send people back to after they sign in. UnoPim tells you the exact address.</p><p>In UnoPim, go to <strong>Configuration → System Settings → Microsoft SSO</strong>.</p><p>The <strong>Redirect URI</strong> box at the top is read-only. Click the copy icon at its right-hand edge to copy the value.</p><p>It will look something like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-unopim-site.com/admin/login/sso/microsoft/callback</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Copy it, do not type it</p><p>Microsoft compares this address letter for letter. A missing <code>s</code> in <code>https</code>, a wrong port number, or an extra <code>/</code> at the end will make the login fail. Always copy it from this screen.</p></div><hr><h2 id="step-3-—-register-unopim-in-microsoft" tabindex="-1">Step 3 — Register UnoPim in Microsoft <a class="header-anchor" href="#step-3-—-register-unopim-in-microsoft" aria-label="Permalink to &quot;Step 3 — Register UnoPim in Microsoft&quot;">​</a></h2><ol><li>In <a href="https://portal.azure.com" target="_blank" rel="noreferrer">portal.azure.com</a>, go to <strong>Microsoft Entra ID → App registrations</strong>.</li><li>Click <strong>+ New registration</strong>.</li><li><strong>Name</strong> — type something you will recognise later, such as <code>UnoPim</code>.</li><li><strong>Supported account types</strong> — choose <strong>Accounts in this organizational directory only (Single tenant)</strong>.</li><li><strong>Redirect URI</strong> — set the dropdown to <strong>Web</strong> and paste the address you copied in Step 2.</li><li>Click <strong>Register</strong>.</li></ol><hr><h2 id="step-4-—-copy-the-client-id-and-tenant-id" tabindex="-1">Step 4 — Copy the Client ID and Tenant ID <a class="header-anchor" href="#step-4-—-copy-the-client-id-and-tenant-id" aria-label="Permalink to &quot;Step 4 — Copy the Client ID and Tenant ID&quot;">​</a></h2><p>Microsoft now shows an <strong>Overview</strong> page with the first two values you need.</p><table tabindex="0"><thead><tr><th>On the Microsoft page</th><th>Paste into UnoPim as</th></tr></thead><tbody><tr><td>Application (client) ID</td><td>Client ID</td></tr><tr><td>Directory (tenant) ID</td><td>Tenant ID</td></tr></tbody></table><p>Copy both somewhere safe for a moment.</p><hr><h2 id="step-5-—-create-the-client-secret" tabindex="-1">Step 5 — Create the Client Secret <a class="header-anchor" href="#step-5-—-create-the-client-secret" aria-label="Permalink to &quot;Step 5 — Create the Client Secret&quot;">​</a></h2><ol><li>In the left menu of your app registration, click <strong>Certificates &amp; secrets</strong>.</li><li>On the <strong>Client secrets</strong> tab, click <strong>+ New client secret</strong>.</li><li>Type a description, choose an expiry period, and click <strong>Add</strong>.</li><li>Copy the value in the <strong>Value</strong> column straight away.</li></ol><div class="danger custom-block"><p class="custom-block-title">You only get one chance to copy this</p><p>Copy the <strong>Value</strong> column, not the <strong>Secret ID</strong>. As soon as you leave this page the value is hidden forever and you have to create a new secret.</p><p>Also note the expiry date in your calendar. When a secret expires, Microsoft sign-in simply stops working with no warning.</p></div><hr><h2 id="step-6-—-approve-the-permission" tabindex="-1">Step 6 — Approve the permission <a class="header-anchor" href="#step-6-—-approve-the-permission" aria-label="Permalink to &quot;Step 6 — Approve the permission&quot;">​</a></h2><ol><li>In the left menu, click <strong>API permissions</strong>.</li><li>You should see <strong>Microsoft Graph → User.Read</strong>. If it is missing, click <strong>+ Add a permission → Microsoft Graph → Delegated permissions</strong>, tick <strong>User.Read</strong>, and confirm.</li><li>Click <strong>Grant admin consent for &lt;your directory&gt;</strong>, then <strong>Yes</strong>.</li></ol><p>This lets UnoPim read the signed-in person&#39;s name and email address. Approving it centrally means your team is not asked to approve anything themselves.</p><hr><h2 id="step-7-—-create-a-microsoft-user-to-test-with" tabindex="-1">Step 7 — Create a Microsoft user to test with <a class="header-anchor" href="#step-7-—-create-a-microsoft-user-to-test-with" aria-label="Permalink to &quot;Step 7 — Create a Microsoft user to test with&quot;">​</a></h2><p>Skip this if the people who will use UnoPim already have accounts in your directory.</p><ol><li>Go to <strong>Microsoft Entra ID → Users → All users</strong>.</li><li>Click <strong>+ New user → Create new user</strong>.</li><li><strong>User principal name</strong> — type a short name such as <code>pimtest</code>, then pick your <code>.onmicrosoft.com</code> domain from the dropdown next to it. The full address becomes something like <code>pimtest@yourcompany.onmicrosoft.com</code>.</li><li><strong>Display name</strong> — for example <code>PIM Test</code>.</li><li>Choose <strong>Auto-generate password</strong> and copy the password shown, or set your own.</li><li>Click <strong>Review + create</strong>, then <strong>Create</strong>.</li></ol><p>The first time this person signs in, Microsoft asks them to change their password. That is normal.</p><hr><h2 id="step-8-—-create-the-matching-user-in-unopim" tabindex="-1">Step 8 — Create the matching user in UnoPim <a class="header-anchor" href="#step-8-—-create-the-matching-user-in-unopim" aria-label="Permalink to &quot;Step 8 — Create the matching user in UnoPim&quot;">​</a></h2><p><strong>Do not skip this step.</strong> Without it, everything else is configured correctly and the login will still be refused.</p><ol><li>In UnoPim go to <strong>Settings → Users → Create</strong>.</li><li><strong>Email</strong> — must be exactly the same as the Microsoft account, for example <code>pimtest@yourcompany.onmicrosoft.com</code>.</li><li><strong>Status</strong> — Active.</li><li><strong>Role</strong> — choose a role that actually gives access to something.</li><li><strong>Password</strong> — set anything. Microsoft sign-in never uses it.</li><li>Save.</li></ol><div class="warning custom-block"><p class="custom-block-title">Give the role real permissions</p><p>If the role has no permissions, the person signs in successfully and is immediately signed out again with a &quot;not authorised&quot; message, because there is no page they are allowed to open.</p><p>Also remember that ticking a section in the role is not always enough — tick the specific pages inside it as well.</p></div><p>Repeat this step for every person who should be able to sign in with Microsoft.</p><hr><h2 id="step-9-—-enter-the-details-in-unopim" tabindex="-1">Step 9 — Enter the details in UnoPim <a class="header-anchor" href="#step-9-—-enter-the-details-in-unopim" aria-label="Permalink to &quot;Step 9 — Enter the details in UnoPim&quot;">​</a></h2><p>Go to <strong>Configuration → System Settings → Microsoft SSO</strong> and fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td>Enable Microsoft SSO</td><td>Turn on</td></tr><tr><td>Tenant ID</td><td>Directory (tenant) ID from Step 4. Your <code>.onmicrosoft.com</code> domain also works.</td></tr><tr><td>Client ID</td><td>Application (client) ID from Step 4</td></tr><tr><td>Client Secret</td><td>The secret <strong>Value</strong> from Step 5</td></tr></tbody></table><p>Click <strong>Save</strong>.</p><p>The <strong>Sign in with Microsoft</strong> button appears on the login page as soon as all four are filled in. If any one of them is empty, the button stays hidden.</p><hr><h2 id="step-10-—-try-it" tabindex="-1">Step 10 — Try it <a class="header-anchor" href="#step-10-—-try-it" aria-label="Permalink to &quot;Step 10 — Try it&quot;">​</a></h2><ol><li>Sign out, or open the login page in a private browser window.</li><li>Click <strong>Sign in with Microsoft</strong>.</li><li>Sign in with the Microsoft account from Step 7 and change the password if prompted.</li><li>You are taken into the UnoPim admin panel.</li></ol><hr><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><h3 id="please-check-your-credentials-and-try-again-—-and-the-email-is-already-filled-in" tabindex="-1">&quot;Please check your credentials and try again&quot; — and the email is already filled in <a class="header-anchor" href="#please-check-your-credentials-and-try-again-—-and-the-email-is-already-filled-in" aria-label="Permalink to &quot;&quot;Please check your credentials and try again&quot; — and the email is already filled in&quot;">​</a></h3><p>This is the most common message, and it is actually a good sign. It means Microsoft accepted the sign-in and sent the email address back to UnoPim. UnoPim then refused it.</p><p>Almost always, the reason is that <strong>no UnoPim user exists with that email address</strong>. Go back to Step 8 and compare the address character by character with the one filled into the form.</p><p>Other possible reasons:</p><ul><li>The UnoPim user exists but is an <strong>API user</strong>, which cannot sign in.</li><li>The email address was previously used by a different person in your Microsoft directory. UnoPim refuses this on purpose, so the new person does not inherit the old person&#39;s access.</li></ul><div class="tip custom-block"><p class="custom-block-title">Why the message is so vague</p><p>The message is intentionally the same for every failure. A more specific message would let an outsider work out which email addresses are UnoPim administrators by trying them one at a time.</p></div><h3 id="your-account-is-not-activated" tabindex="-1">&quot;Your account is not activated&quot; <a class="header-anchor" href="#your-account-is-not-activated" aria-label="Permalink to &quot;&quot;Your account is not activated&quot;&quot;">​</a></h3><p>The UnoPim user exists but is switched off. Go to <strong>Settings → Users</strong>, edit the user, and set Status to Active.</p><h3 id="selected-user-account-does-not-exist-in-tenant" tabindex="-1">&quot;Selected user account does not exist in tenant …&quot; <a class="header-anchor" href="#selected-user-account-does-not-exist-in-tenant" aria-label="Permalink to &quot;&quot;Selected user account does not exist in tenant …&quot;&quot;">​</a></h3><p>The Microsoft account you signed in with does not belong to the directory that owns the app registration.</p><ul><li>If the message mentions <strong>Microsoft Services</strong>, you were signing in with a personal Microsoft account. Go back to Step 1.</li><li>If it names your own directory, sign in with a user from Step 7, or invite the outside account as a guest under <strong>Users → New user → Invite external user</strong>.</li></ul><h3 id="the-azure-portal-will-not-let-you-sign-in" tabindex="-1">The Azure portal will not let you sign in <a class="header-anchor" href="#the-azure-portal-will-not-let-you-sign-in" aria-label="Permalink to &quot;The Azure portal will not let you sign in&quot;">​</a></h3><p>The Azure and Entra portals do not accept personal Microsoft accounts. You need an account that belongs to a directory. Completing the Azure sign-up in Step 1 creates one for you.</p><h3 id="reply-url-does-not-match-or-a-redirect-error" tabindex="-1">&quot;Reply URL does not match&quot; or a redirect error <a class="header-anchor" href="#reply-url-does-not-match-or-a-redirect-error" aria-label="Permalink to &quot;&quot;Reply URL does not match&quot; or a redirect error&quot;">​</a></h3><p>The address registered in Microsoft does not exactly match the one UnoPim sends. Copy the Redirect URI from Step 2 again and compare it with what is listed under <strong>Authentication</strong> in your app registration.</p><p>If your UnoPim site address has changed since you set this up, the Redirect URI has changed too and must be updated in Microsoft.</p><h3 id="the-signed-in-user-is-not-assigned-to-a-role-for-the-application" tabindex="-1">&quot;The signed in user is not assigned to a role for the application&quot; <a class="header-anchor" href="#the-signed-in-user-is-not-assigned-to-a-role-for-the-application" aria-label="Permalink to &quot;&quot;The signed in user is not assigned to a role for the application&quot;&quot;">​</a></h3><p>You have turned on <strong>Assignment required?</strong> for the application, and this person is not on the list. Go to <strong>Microsoft Entra ID → Enterprise applications → your app → Users and groups</strong> and add them, or add them to the group you assigned.</p><h3 id="it-used-to-work-and-now-it-does-not" tabindex="-1">It used to work and now it does not <a class="header-anchor" href="#it-used-to-work-and-now-it-does-not" aria-label="Permalink to &quot;It used to work and now it does not&quot;">​</a></h3><p>The client secret has most likely expired. Go to <strong>Certificates &amp; secrets</strong>, create a new one, and paste the new <strong>Value</strong> into UnoPim.</p><h3 id="signing-in-works-then-immediately-signs-out" tabindex="-1">Signing in works, then immediately signs out <a class="header-anchor" href="#signing-in-works-then-immediately-signs-out" aria-label="Permalink to &quot;Signing in works, then immediately signs out&quot;">​</a></h3><p>The role assigned to that user in UnoPim does not grant access to any page. Edit the role and give it real permissions.</p><h3 id="the-button-does-not-appear-on-the-login-page" tabindex="-1">The button does not appear on the login page <a class="header-anchor" href="#the-button-does-not-appear-on-the-login-page" aria-label="Permalink to &quot;The button does not appear on the login page&quot;">​</a></h3><p>All four fields must be filled in — the toggle, Tenant ID, Client ID, and Client Secret. If any one is blank, the button is hidden.</p><hr><h2 id="only-some-of-your-staff-use-unopim" tabindex="-1">Only some of your staff use UnoPim <a class="header-anchor" href="#only-some-of-your-staff-use-unopim" aria-label="Permalink to &quot;Only some of your staff use UnoPim&quot;">​</a></h2><p>A common situation: your company has 500 people in Microsoft, but only 50 work in the PIM.</p><p>You do not have to do anything for this. Everyone can click <strong>Sign in with Microsoft</strong>, but only people who also have a UnoPim user account get in. The other 450 are turned away with the &quot;check your credentials&quot; message. Your UnoPim user list is the gate.</p><p>If you would rather stop people earlier — before they even come back to UnoPim — you can tell Microsoft to allow only certain people to use the application:</p><ol><li>Go to <strong>Microsoft Entra ID → Enterprise applications</strong> and open the app you registered.</li><li>Open <strong>Properties</strong> and set <strong>Assignment required?</strong> to <strong>Yes</strong>.</li><li>Open <strong>Users and groups</strong> and add only the people, or a group, who should use UnoPim.</li></ol><p>Anyone not on that list now sees a Microsoft error instead of reaching UnoPim at all.</p><div class="tip custom-block"><p class="custom-block-title">Use a group</p><p>Assigning a group such as <code>PIM Users</code> rather than individuals means adding someone to that group is all it takes to grant access, and removing them takes it away. Your IT team can manage it without touching UnoPim.</p></div><p>You still need to create the matching UnoPim user from Step 8 either way.</p><hr><h2 id="day-to-day-management" tabindex="-1">Day-to-day management <a class="header-anchor" href="#day-to-day-management" aria-label="Permalink to &quot;Day-to-day management&quot;">​</a></h2><p><strong>Adding someone new.</strong> Create their Microsoft account in your directory, then create a UnoPim user with the same email address and a role. Both are required.</p><p><strong>Removing someone.</strong> Disable them in your Microsoft directory, and also set their UnoPim user to Inactive. Either one alone blocks Microsoft sign-in, but doing both is safest.</p><p><strong>Changing what someone can do.</strong> Change their role in UnoPim under <strong>Settings → Users</strong>. Microsoft has no say in this.</p><p><strong>Someone changed their email address in Microsoft.</strong> They can keep signing in. UnoPim remembers the person, not the address, after their first successful sign-in.</p><p><strong>Rotating the secret.</strong> Create a new client secret in Microsoft before the old one expires, paste the new value into UnoPim, then delete the old secret in Microsoft.</p>',103)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
